<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigHostAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigHostAccessor trait.
 *
 * Covers null default, string/VO assignment via withHost,
 * getHost/host accessors, and isHostChanged with/without original.
 */
class SmtpOutboundConfigHostAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withHost creates a new instance with the Host set
     * from a string value, and getHost returns the primitive string.
     */
    public function testWithHostFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigHostAccessorUnitTest();

        // Act
        $result = $holder->withHost('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getHost());
    }
    /**
     * Asserts that withhost has access to the value object
     * from a string value, and getHost returns the primitive string.
     */
    public function testWithHostFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigHostAccessorUnitTest();

        // Act
        $result = $holder->withHost('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->host()->value());
    }
    public function testChangedHost(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigHostAccessorUnitTest()->withHost('one');
        $original = $holder->withHost('one');
        $same = $holder->withHost('one');
        $modified = $holder->withHost('other');

        // Act
        $withSame = $original->isHostChanged($same);
        $withDiferent = $original->isHostChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigHostAccessorUnitTest
{
    use SmtpOutboundConfigHostAccessor;
}
